package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PerformanceAppealPermissionGuardTest{private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);private final PerformanceAppealPermissionGuard guard=new PerformanceAppealPermissionGuard(client);@Test void actionsAndScopesRemainIndependent(){when(client.resolve(PerformanceAppealPermissionGuard.FEATURE,"t")).thenReturn(new EffectiveFeaturePermission(PerformanceAppealPermissionGuard.FEATURE,false,true,true,true,false,false,true,false,false,false,false,PermissionDataScope.OWN_RECORDS));assertThat(guard.require(PrimeHrAction.ADD,"t")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThat(guard.require(PrimeHrAction.SUBMIT,"t")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThatThrownBy(()->guard.require(PrimeHrAction.APPROVE,"t")).isInstanceOf(AccessDeniedException.class);}}
